import {FormControl, Textarea} from '@primer/react'
import {useEffect} from 'react'

// Maximum prompt length allowed by the sweagentd API
// See: https://github.com/github/sweagentd/blob/main/internal/problemstatement/problemstatement.go#L43
export const MAX_LENGTH = 30000

export const CCAPrompt = ({
  ref,
  prompt,
  onPromptChange,
  isValid,
  setIsValid,
}: {
  ref?: React.Ref<HTMLTextAreaElement>
  prompt: string
  onPromptChange: (value: string) => void
  isValid: boolean
  setIsValid: (isValid: boolean) => void
}) => {
  useEffect(() => {
    setIsValid(prompt.length <= MAX_LENGTH)
  }, [prompt.length, setIsValid])

  return (
    <FormControl>
      <FormControl.Label>Prompt</FormControl.Label>
      <FormControl.Caption>
        {prompt.length} / {MAX_LENGTH} characters
      </FormControl.Caption>
      <Textarea
        block
        ref={ref}
        value={prompt}
        onChange={e => onPromptChange(e.target.value)}
        placeholder="Describe what you want Copilot to build"
        validationStatus={isValid ? undefined : 'error'}
      />
      {!isValid && (
        <FormControl.Validation variant="error">
          Prompt may not be longer than {MAX_LENGTH} characters
        </FormControl.Validation>
      )}
    </FormControl>
  )
}
CCAPrompt.displayName = 'CCAPrompt'
