import type {Visibility} from '@github-ui/repos-list'

import type {OwnerSelection} from '../types/repo-creation-types'

export const getVisibilityOptions = ({
  ownerSelection,
  currentUserIsEnterpriseManaged,
}: {
  ownerSelection?: OwnerSelection
  currentUserIsEnterpriseManaged: boolean
}): VisibilityWithRestriction[] => {
  // The public option should be explicitly removed for enterprise managed users
  const visibilitiesWithRestrictions: VisibilityWithRestriction[] = currentUserIsEnterpriseManaged
    ? []
    : [{visibility: 'public', message: publicVisibilityRestriction(ownerSelection)}]

  if (ownerSelection?.businessName) {
    visibilitiesWithRestrictions.push({visibility: 'internal', message: internalVisibilityRestriction(ownerSelection)})
  }

  visibilitiesWithRestrictions.push({
    visibility: 'private',
    message: privateVisibilityRestriction(ownerSelection),
  })

  return visibilitiesWithRestrictions
}

export interface VisibilityWithRestriction {
  visibility: Visibility
  message?: string
}

const RESTRICTED_BY_ORG_POLICY_MESSAGE = 'Restricted by organization policy'
const RESTRICTED_BY_ORG_RULESET_MESSAGE = 'Restricted by organization ruleset'

const NOT_SUPPORTED_FOR_OWNER = 'Not supported for selected owner'

export const getDisplayedVisibilitiesWithRules = ({
  displayedVisibilities,
  rulesAllowedVisibilities,
}: {
  displayedVisibilities: VisibilityWithRestriction[]
  rulesAllowedVisibilities: Visibility[]
}) => {
  return displayedVisibilities.map(visibilityWithRestriciton => {
    const visibility = visibilityWithRestriciton.visibility
    if (!rulesAllowedVisibilities.includes(visibility)) {
      return {
        visibility,
        message: RESTRICTED_BY_ORG_POLICY_MESSAGE,
      }
    }
    return visibilityWithRestriciton
  })
}

const publicVisibilityRestriction = (ownerSelection?: OwnerSelection) => {
  if (!ownerSelection) return

  const {publicRestrictedByPolicy, publicRestrictedByRulesets, displayedVisibilities} = ownerSelection

  if (publicRestrictedByPolicy) {
    return RESTRICTED_BY_ORG_POLICY_MESSAGE
  }

  if (publicRestrictedByRulesets) {
    return RESTRICTED_BY_ORG_RULESET_MESSAGE
  }

  if (!displayedVisibilities.includes('public')) {
    return NOT_SUPPORTED_FOR_OWNER
  }
}

const internalVisibilityRestriction = (ownerSelection?: OwnerSelection) => {
  if (!ownerSelection) return

  const {internalRestrictedByPolicy, internalRestrictedByRulesets} = ownerSelection

  if (internalRestrictedByPolicy) {
    return RESTRICTED_BY_ORG_POLICY_MESSAGE
  }

  if (internalRestrictedByRulesets) {
    return RESTRICTED_BY_ORG_RULESET_MESSAGE
  }
}

const privateVisibilityRestriction = (ownerSelection?: OwnerSelection) => {
  if (!ownerSelection) return

  const {privateRestrictedByPolicy, privateRestrictedByRulesets, privateRestrictedByPlan, adminableByCurrentUser} =
    ownerSelection

  if (isIndividualTradeRestricted(ownerSelection) || isAdminOfTradeRestrictedOrg(ownerSelection)) {
    return 'Disabled by regional policies'
  }

  const tradeRestrictedNonOrgAdmin = isOrgWithTradeControls(ownerSelection) && !adminableByCurrentUser

  if (privateRestrictedByPolicy || tradeRestrictedNonOrgAdmin) {
    return RESTRICTED_BY_ORG_POLICY_MESSAGE
  }

  if (privateRestrictedByRulesets) {
    return RESTRICTED_BY_ORG_RULESET_MESSAGE
  }

  if (privateRestrictedByPlan) {
    return 'Current plan does not support private repositories'
  }
}

const isOrgWithTradeControls = (ownerSelection: OwnerSelection) => {
  const {isOrganization, hasTradeRestrictions} = ownerSelection
  return isOrganization && hasTradeRestrictions
}

export const isIndividualTradeRestricted = (ownerSelection: OwnerSelection) => {
  const {isOrganization, hasTradeRestrictions} = ownerSelection
  return !isOrganization && hasTradeRestrictions
}

export const isAdminOfTradeRestrictedOrg = (ownerSelection: OwnerSelection) =>
  isOrgWithTradeControls(ownerSelection) && ownerSelection.adminableByCurrentUser
