import type {Visibility} from '@github-ui/repos-list'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'

// Returns the allowed visibilities for a proposed repository. If the owner is not
// an organization, it will return undefined.
export async function getRulesAllowedVisibilitiesForProposedRepository({
  owner,
  name,
}: {
  owner: string
  name: string
}): Promise<Visibility[] | undefined> {
  if (owner) {
    const apiURL = `/repositories/check-rule-state-for-proposed-repository`

    const response = await verifiedFetchJSON(apiURL, {
      method: 'POST',
      body: {owner, name},
    })

    try {
      if (response.ok) {
        const result = await response.json()
        return result?.allowedVisibilities
      }
      // error fetching rule state
      // just be permissive and rely on server submission to enforce any policy violations
      return undefined
    } catch {
      // error fetching rule state
      // just be permissive and rely on server submission to enforce any policy violations
      return undefined
    }
  }
}
