import {PropertiesValuesTable} from '@github-ui/custom-properties-core/components/PropertiesValuesTable'
import type {PropertyField} from '@github-ui/custom-properties-core/hooks/use-edit-custom-properties'
import type {PropertyDefinition, PropertyDefinitionBase, PropertyValue} from '@github-ui/custom-properties-types'
import {Text} from '@primer/styled-react'
import {useMemo} from 'react'

export function RequiredCustomPropertiesSelection({
  definitions,
  editableDefinitions,
  propertyValuesMap,
  setPropertyValue,
  revertPropertyValue,
  fetchAllowedValuesUrl,
}: {
  definitions: PropertyDefinition[]
  editableDefinitions: PropertyDefinition[]
  propertyValuesMap: Record<string, PropertyField>
  setPropertyValue: (propertyName: string, value: PropertyValue) => void
  revertPropertyValue: (propertyName: string) => void
  fetchAllowedValuesUrl?: (propertyName: string) => string
}) {
  const editableDefinitionsSet = useMemo(
    () => new Set((editableDefinitions || []).map((definition: PropertyDefinitionBase) => definition.propertyName)),
    [editableDefinitions],
  )

  return (
    <div data-testid="custom-properties-selection">
      <Text sx={{display: 'block', fontSize: 3}}>Required properties</Text>
      <Text sx={{display: 'block', color: 'fg.muted', mb: 2}}>
        This repository will be initialized with the following, per organization policy.
      </Text>
      <PropertiesValuesTable
        definitions={definitions}
        propertyValuesMap={propertyValuesMap}
        rowRenderer={(rowProps, setRef) => {
          const {definition} = rowProps
          const isEditable = editableDefinitionsSet.has(definition.propertyName)

          if (isEditable) {
            return (
              <PropertiesValuesTable.EditValueRow
                setRef={setRef}
                {...rowProps}
                required={definition.requireExplicitValues}
                onChange={setPropertyValue}
                onReset={revertPropertyValue}
                fetchAllowedValuesUrl={fetchAllowedValuesUrl}
                showUndo={false}
              />
            )
          }
          return <PropertiesValuesTable.FormReadValueRow {...rowProps} required={definition.requireExplicitValues} />
        }}
      />
    </div>
  )
}
